export const SASI_IDENTITY_MARKERS=[
 "/* R12 SASI conversation identity — user text is blue before and after send. */",
 "/* R12R1 SASI conversation identity — user text stays blue before and after send. */",
 "/* R12R2 SASI conversation identity */",
 "/* R12R3 SASI conversation identity */",
];

export function stripOwnedIdentityTail(src){
 let cut=-1;
 for(const marker of SASI_IDENTITY_MARKERS){
  const i=src.indexOf(marker);
  if(i>=0&&(cut<0||i<cut))cut=i;
 }
 if(cut<0)return src;
 // These markers were generated by our installer at EOF. Truncate only the owned tail.
 return src.slice(0,cut).trimEnd()+"\n";
}

export function sasiIdentityBlock(){
 return [
  "/* R12R3 SASI conversation identity */",
  '.lx-sasi-user-bubble[data-sasi-user-color="blue"]{',
  '  color:#2563eb!important;',
  '  -webkit-text-fill-color:#2563eb!important;',
  '}',
  '.lx-sasi-reference-textarea{',
  '  color:#2563eb!important;',
  '  caret-color:#2563eb!important;',
  '}',
  ""
 ].join("\n");
}

export function repairSasiIdentityCss(src){
 const base=stripOwnedIdentityTail(String(src||""));
 return base+sasiIdentityBlock();
}
